<script lang="ts">
 import {auth} from '#lib/auth.svelte.ts';
 let password=$state(''),code=$state(''),uri=$state(''),codes=$state<string[]>([]),busy=$state(false),error=$state(''),message=$state('');
 const setupSecret=$derived(uri?new URL(uri).searchParams.get('secret')??'':'');
 async function run(task:()=>Promise<void>){busy=true;error='';try{await task();}catch(e){error=(e as Error).message;}finally{busy=false;password='';code='';}}
 async function setup(){await run(async()=>{const result=await auth.beginMfa(password);uri=result?.totpURI??'';codes=result?.backupCodes??[];});}
 async function verify(){await run(async()=>{await auth.verifyMfa(code);uri='';message='Authenticator verified. Keep your recovery codes offline.';});}
 async function recover(){await run(async()=>{const result=await auth.regenerateBackupCodes(password);codes=result?.backupCodes??[];message='New recovery codes replace your previous codes.';});}
</script>
<svelte:head><title>Account security — PuntersEdge</title></svelte:head>
<section class="surface mx-auto max-w-2xl space-y-5 p-6"><h1 class="text-3xl font-bold">Account security</h1>{#if !auth.signedIn}<a href="/login?next=/account/security" class="btn-primary">Sign in to secure your account</a>{:else}<p class="text-haze">Authenticator protection is required for administration. Passwords, setup keys and recovery codes are never included in activity logs.</p><p>Authenticator: {auth.viewer?.twoFactorEnabled?'Enabled':'Setup required'}</p>{#if uri}<p class="text-sm text-haze">In your authenticator, choose a manual setup key, name it PuntersEdge and select time-based codes (TOTP). Enter the key below, then verify the six-digit code. Keep this key private.</p><label class="block">Manual authenticator setup key<input class="field mt-2 w-full font-mono text-sm" readonly value={setupSecret} autocomplete="off" spellcheck="false"/></label><details class="rounded-xl border border-line p-3"><summary class="cursor-pointer text-sm">Full setup URI for compatible password managers</summary><label class="mt-3 block">Add this setup URI to your authenticator app<textarea class="mt-2 w-full rounded-xl border border-line bg-ink p-3 text-xs" readonly value={uri} rows="4" spellcheck="false"></textarea></label></details><label class="block">Six-digit authenticator code<input class="field mt-2 w-full" bind:value={code} autocomplete="one-time-code" inputmode="numeric"/></label><button class="btn-primary" disabled={busy} onclick={verify}>Verify authenticator</button>{:else}<label class="block">Current password<input class="field mt-2 w-full" bind:value={password} type="password" autocomplete="current-password"/></label><button class="btn-primary" disabled={busy||!password} onclick={auth.viewer?.twoFactorEnabled?recover:setup}>{auth.viewer?.twoFactorEnabled?'Generate new recovery codes':'Set up authenticator'}</button>{/if}{#if codes.length}<div class="rounded-xl border border-book p-4"><h2 class="font-bold text-book">Save these recovery codes securely</h2><p class="mt-2 text-sm">Each code can be used once if your authenticator is unavailable. These are shown only in this session.</p><ul class="mt-3 grid grid-cols-2 gap-2 font-mono text-sm">{#each codes as item}<li>{item}</li>{/each}</ul><button class="btn-ghost mt-4" onclick={()=>codes=[]}>I saved my recovery codes</button></div>{/if}<a href="/admin" class="btn-ghost inline-flex">Open administration</a>{/if}{#if error}<p role="alert" class="text-loss">{error}</p>{/if}{#if message}<p role="status" class="text-model">{message}</p>{/if}</section>
